INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1048, 'plPL', 'W głąb Szkarłatnego Klasztoru', 'Podczas gdy Mroczna Pani zajmuje się palącą kwestią natarcia Króla Lisza na północy, ja dopilnowuję, by sprawy bliżej domu zostały należycie załatwione.$b$bNie ma wątpliwości, że ludzkie szkodniki, które nazywają się Szkarłatną Krucjatą, są najostrzejszym cierniem w naszym boku tu, na miejscu. Po Polanach Tirisfal dosłownie roi się od tych małych czerwonych mrówek.$b$bUdaj się do Klasztoru, $N, i zgładź nadinkwizytorkę Białowłosą oraz jej najważniejszych zastępców.', 'Zabij nadinkwizytorkę Białowłosą, szkarłatnego komandora Mograine\'a, Heroda – Szkarłatnego czempiona – oraz tresera ogarów Lokseya, a potem złóż raport Varimathrasowi w Podmieście.', '', 'Wróć do Varimathrasa w Królewskim Kwartale w Podmieście.', '', '', '', '', 0),
(11392, 'plPL', 'Wezwij Bezgłowego Jeźdźca', 'Tę dyniową kapliczkę zdobi wiele posępnych świec.', 'Zanieś posępną świecę do luźno przekopanej ziemi.', '', 'Wróć do luźno przekopanej ziemi w Szkarłatnym Klasztorze.', '', '', '', '', 0),
(11401, 'plPL', 'Wezwij Bezgłowego Jeźdźca', 'Tę dyniową kapliczkę zdobi wiele posępnych świec, a ona sama szczerzy się szyderczo...', 'Zanieś posępną świecę do luźno przekopanej ziemi.', '', 'Wróć do luźno przekopanej ziemi w Szkarłatnym Klasztorze.', '', '', '', '', 0),
(11404, 'plPL', 'Wezwij Bezgłowego Jeźdźca', 'Tę dyniową kapliczkę zdobi wiele posępnych świec, a ona sama szczerzy się szyderczo...', 'Zanieś posępną świecę do luźno przekopanej ziemi.', '', 'Wróć do luźno przekopanej ziemi w Szkarłatnym Klasztorze.', '', '', '', '', 0),
(11405, 'plPL', 'Wezwij Bezgłowego Jeźdźca', 'Tę dyniową kapliczkę zdobi wiele posępnych świec, a ona sama szczerzy się szyderczo...', 'Zanieś posępną świecę do luźno przekopanej ziemi.', '', 'Wróć do luźno przekopanej ziemi w Szkarłatnym Klasztorze.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(1048, 'plPL', 'Dobrze $gsłużyłeś:służyłaś; Mrocznej Pani, $N. Niemałe to było zadanie, o które cię prosiłem.$b$bTwoja lojalność wobec Porzuconych została odnotowana. A twoja nieustępliwość w walce zostanie zapamiętana.', 0),
(11404, 'plPL', 'Czy położysz świecę i wezwiesz Bezgłowego Jeźdźca z jego przeklętego spoczynku?', 0),
(11405, 'plPL', 'Czy położysz świecę i wezwiesz Bezgłowego Jeźdźca z jego przeklętego spoczynku?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(1048, 'plPL', 'Być może nie wyraziłem się dość jasno, $N. Chcę, by nadinkwizytorka Białowłosa zginęła raz na zawsze. A przy okazji pozbądź się też jej najwyższych dowódców.$B$BZabij tego fanatyka, szkarłatnego komandora Mograine\'a. Zgładź Heroda, Szkarłatnego czempiona. I wyrżnij tresera ogarów Lokseya razem z jego parszywymi kundlami.$B$BA teraz precz!', 0),
(11405, 'plPL', 'Tę ziemię ktoś niedawno poruszył. W wierzchniej warstwie wiją się dżdżownice, próbując uciec przed mrocznymi głębinami pod sobą.', 0);
