INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2151, 'plPL', 'Arellas Ognisty Liść$BNajwyższy czarodziej Szkarłatnej Krucjaty$BObywatel Quel\'Thalas$BUwięziony w wiecznej walce z nekromantą Diesalvenem', 0),
(2152, 'plPL', 'Admirał Barean Zachodni Wiatr$BWielki admirał Szkarłatnej Floty$BObywatel Kul Tiras$BZaginiony u Zamarzniętego Wybrzeża Północnej Grani', 0),
(2153, 'plPL', 'Dorgar Kamiennobrwy$BWojownik Szkarłatnej Krucjaty$BPan Czerwonych Pieczar$BOstatnio widziany w Górach Alterak', 0),
(2171, 'plPL', 'Fellari Chyża Strzała$BKapitan tropicieli Szkarłatnej Krucjaty$BObywatelka Quel\'Thalas$BZaginiona w lasach Srebrzystego Boru', 0),
(2172, 'plPL', 'Ferren Marcus$BNajwyższy opat Szkarłatnego Klasztoru$BObywatel Stratholmu$BPoległ w obronie Szkarłatnego Klasztoru podczas Pierwszego Letniego Szturmu', 0),
(2173, 'plPL', 'Harthal Prawdziwy Wzrok$BLord paladyn Szkarłatnej Krucjaty$BObywatel Azeroth – rycerz Srebrnej Dłoni$BOstatnio widziany, gdy wkraczał do przeklętego miasta Stratholm', 0),
(2174, 'plPL', 'Holia Słoneczna Tarcza$BObrończyni Szkarłatnej Krucjaty$BPoległa, zabijając upiornego władcę Beltherisa', 0),
(2175, 'plPL', 'Invar Jednoręki$BPierwszy główny zabójca Szkarłatnej Krucjaty$BObywatel Dalaranu$BOstatnio widziany na wybrzeżach Północnej Grani', 0),
(2176, 'plPL', 'Orman ze Stromgardu$BPierwszy kapitan generalny Szkarłatnej Krucjaty$BObywatel Stromgardu$BZaginiony u wylotu Lodowca Lodowej Korony', 0),
(2177, 'plPL', 'Valea Bliźniacze Ostrza$BWojowniczka Szkarłatnej Krucjaty$BObywatelka Alterak$BOstatnio widziana w głębi Wschodnich Plagowisk', 0),
(2178, 'plPL', 'Yana Krwawa Włócznia$BDruga główna zabójczyni Szkarłatnej Krucjaty$BObywatelka Dalaranu$BZaginiona na Polanach Tirisfal', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(4286, 0, 0, 'plPL', 'Nosisz na sobie skazę Plagi. Szykuj się na podróż do Wypaczonej Otchłani.'),
(4286, 0, 1, 'plPL', 'Nie ma dla ciebie ucieczki. Krucjata zniszczy każdego, kto nosi skazę Plagi.'),
(4286, 0, 2, 'plPL', 'Światłość potępia każdego, kto skrywa w sobie zło. Teraz zginiesz!'),
