INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(2569, 'plPL', 'W końcu i tak zaczniesz mówić. Równie dobrze możesz wszystko wyśpiewać od razu.', 'W końcu i tak zaczniesz mówić. Równie dobrze możesz wszystko wyśpiewać od razu.', 0),
(2570, 'plPL', 'Wyznaj winy, a cię uwolnimy.', 'Wyznaj winy, a cię uwolnimy.', 0),
(2571, 'plPL', 'Co? O nie, nie obchodzi mnie, co masz do powiedzenia. Po prostu lubię zadawać ból.', 'Co? O nie, nie obchodzi mnie, co masz do powiedzenia. Po prostu lubię zadawać ból.', 0),
(6199, 'plPL', 'Nie zbezcześcisz tych tajemnic!', '', 0),
(6200, 'plPL', 'Spłoń w sprawiedliwym ogniu!', '', 0),
(6201, 'plPL', 'Łakniemy zemsty.', '', 0),
(6202, 'plPL', 'Nie ma spoczynku... dla gniewnych umarłych!', '', 0),
(6203, 'plPL', 'Więcej... Więcej dusz!', '', 0),
(6204, 'plPL', 'Mów... mów wszystko!', '', 0),
(6205, 'plPL', 'Oczyszczenie przez ból!', '', 0),
(6206, 'plPL', 'Sprośne sekreciki!', '', 0),
(6207, 'plPL', 'Wydrę sekrety z twojego ciała!', '', 0),
(12378, 'plPL', 'Spopielacz...', 'Spopielacz...', 0),
(12379, 'plPL', 'Na kolana! Na kolana przed Spopielaczem!', 'Na kolana! Na kolana przed Spopielaczem!', 0),
(12380, 'plPL', 'Nie jestem godzien, $gpanie:pani;.', 'Nie jestem godzien, $gpanie:pani;.', 0),
(12381, 'plPL', 'Czy $gprzybyłeś:przybyłaś;, by ocalić ten świat? By go oczyścić?', 'Czy $gprzybyłeś:przybyłaś;, by ocalić ten świat? By go oczyścić?', 0),
(12382, 'plPL', '$gMój panie:Moja pani;, pozwól mi żyć dość długo, bym ujrzał, jak oczyszczasz ten świat z niewiernych.', '$gMój panie:Moja pani;, pozwól mi żyć dość długo, bym ujrzał, jak oczyszczasz ten świat z niewiernych.', 0),
(12383, 'plPL', 'I tak to się zaczyna...', 'I tak to się zaczyna...', 0),
(12384, 'plPL', 'Weź mnie ze sobą, $gpanie:pani;.', 'Weź mnie ze sobą, $gpanie:pani;.', 0),
(12480, 'plPL', 'Nareszcie klątwa została zdjęta. Dziękuję ci, $gbohaterze:bohaterko;.', '', 0),
(12481, 'plPL', 'Klątwa? Co tu się dzieje, Fairbanks?', 'Klątwa? Co tu się dzieje, Fairbanks?', 0),
(12482, 'plPL', 'Chcesz powiedzieć, że nie wiesz? Miecz, który nosisz na plecach, zwie się Spopielaczem – tak nazwano go od przydomka jego pierwszego właściciela.', '', 0),
(12483, 'plPL', 'Mograine?', 'Mograine?', 0),
(12484, 'plPL', 'Tak, najwyższy lord Mograine: jeden z założycieli pierwotnego zakonu Szkarłatnej Krucjaty. Rycerz o niezachwianej wierze i czystości. Mograine miał zostać zdradzony przez własnego syna i zabity przez siły Kel\'Thuzada w Stratholmie. Tak właśnie tu trafiłem...', '', 0),
(12486, 'plPL', 'Krucjatę założyli najwyższy generał Abbendis, wielki inkwizytor Isillien i najwyższy lord Mograine. W swoich początkach Krucjata była szlachetnym zakonem. Szaleństwo i obłąkana żarliwość, które widzisz teraz, nie istniały. Koła zepsucia poszły w ruch dopiero wtedy, gdy pojawił się ten, którego zwą Wielkim Krzyżowcem.', '', 0),
(12487, 'plPL', 'Wciąż nie do końca rozumiem.', 'Wciąż nie do końca rozumiem.', 0),
(12488, 'plPL', 'Najwyższy lord był filarem Krucjaty. Tak, Mograine\'a nazywano Spopielaczem z powodu jego czynów przeciwko armiom Króla Lisza. Uzbrojony jedynie w ostrze i wiarę, Mograine wkraczał w sam środek całych batalionów nieumarłych i wychodził bez szwanku – jedynym znakiem, że w ogóle tam był, były prochy jego wrogów. Czy nie rozumiesz? Bało się go samo oblicze śmierci! Drżało w jego obecności!', '', 0),
(12489, 'plPL', 'Niesamowita historia. Jak więc zginął?', 'Niesamowita historia. Jak więc zginął?', 0),
(12490, 'plPL', 'Tak, jak może zginąć tylko bohater: w wyniku tragedii. Wielki Krzyżowiec zawarł układ z samym Kel\'Thuzadem! Miano urządzić zasadzkę, która skończyłaby się śmiercią Mograine\'a. Zdrada tego rodzaju mogła wyjść tylko od najbardziej zaufanych i najukochańszych towarzyszy.', '', 0),
(12491, 'plPL', 'Chcesz powiedzieć...', 'Chcesz powiedzieć...', 0),
(12492, 'plPL', '<Nadinkwizytor Fairbanks kiwa głową.>$B$BTak, młodszy Mograine, ten zwany Szkarłatnym komandorem – jak podejrzewam, za sprawą knowań Wielkiego Krzyżowca. Poprowadził ojca w zasadzkę jak baranka na rzeź.', '', 0),
(12493, 'plPL', 'Skąd to wszystko wiesz?', 'Skąd to wszystko wiesz?', 0),
(12494, 'plPL', '<Nadinkwizytor Fairbanks unosi tabard, odsłaniając kilka okropnych blizn.>$B$BBo tam byłem... Byłem najbardziej zaufanym doradcą najwyższego lorda. Powinienem był się domyślić... Czułem, że coś jest nie tak, a jednak do tego dopuściłem. Uwierzysz, że było tam tysiąc albo i więcej sług Plagi?', '', 0),
(12495, 'plPL', 'Tysiąc? Na jednego człowieka?', 'Tysiąc? Na jednego człowieka?', 0),
(12496, 'plPL', 'To był Spopielacz, głupcze! Gdy wokół nas zaczęła się materializować Plaga, ostrze Mograine\'a zaczęło jaśnieć... buczeć... Młodszy Mograine uznał to za znak do ucieczki. Rzucili się na nas z głodem, jakiego nigdy wcześniej nie widziałem. A jednak...', '', 0),
(12497, 'plPL', 'A jednak? A jednak co??', 'A jednak? A jednak co??', 0),
(12498, 'plPL', 'To nie wystarczyło.$B$B<Fairbanks przez chwilę uśmiecha się krzywo, pogrążony we wspomnieniach.>$B$BPrzyszło ich tysiąc i tysiąc zginęło. Na Światłość! Na potęgę Mograine\'a! Powalał ich tak szybko, jak nadchodzili. Pośród chaosu zauważyłem, że młodszy Mograine wciąż tam jest, w oddali. Zawołałem do niego: „Pomóż nam, Renault! Pomóż ojcu, chłopcze!”', '', 0),
(12499, 'plPL', 'I pomógł?', 'I pomógł?', 0),
(12500, 'plPL', '<Nadinkwizytor Fairbanks kręci głową.>$B$BNie... Stał z tyłu i patrzył, jak legion nieumarłych na nas spada. Wkrótce potem moje siły się wyczerpały. Padłem pierwszy... Byłem pewien, że rozerwą mnie na strzępy, gdy leżałem nieprzytomny, ale całkowicie mnie zignorowali i skupili całą uwagę na najwyższym lordzie. ', '', 0),
(12501, 'plPL', 'Mów dalej, Fairbanks.', 'Mów dalej, Fairbanks.', 0),
(12502, 'plPL', 'Mogłem jedynie udawać martwego, gdy piętrzyły się na mnie trupy sług Plagi. Była ciemność i tylko stłumione odgłosy bitwy nade mną. Szczęk żelaza, zgrzytanie i chrzęst... straszne, przerażające dźwięki. A potem zapadła cisza. Wołał mnie! „Fairbanks! Fairbanks, gdzie jesteś? Odezwij się, Fairbanks!” A potem rozległ się głos niedowierzania. Ukąszenie zdrady...', '', 0),
(12503, 'plPL', 'Chcesz powiedzieć...', 'Chcesz powiedzieć...', 0),
(12504, 'plPL', 'Chłopak podniósł Spopielacz i przebił nim serce ojca, gdy ten stał odwrócony plecami. Jego ostatnie słowa będą mnie prześladować na zawsze: „Coś ty zrobił, Renault? Dlaczego to zrobiłeś?”', '', 0),
(12505, 'plPL', 'Miałeś rację, Fairbanks. To tragiczne.', 'Miałeś rację, Fairbanks. To tragiczne.', 0),
(12506, 'plPL', 'Ostrze i Mograine stanowili jedność. Rozumiesz? Ten czyn splugawił ostrze i doprowadził do upadku samego Mograine\'a, który stał się rycerzem śmierci Kel\'Thuzada. Przysiągłem, że jeśli przeżyję, zdemaskuję sprawców tej haniebnej zbrodni. Przez dwa dni leżałem pod gnijącymi, zarażonymi truchłami Plagi, zbierając jak najwięcej sił, by uciec ze zrównanego z ziemią miasta.\n', '', 0),
(12507, 'plPL', 'I uciekłeś...', 'I uciekłeś...', 0),
(12508, 'plPL', 'Tak, uciekłem. Ku wielkiemu niezadowoleniu młodszego Mograine\'a wróciłem do Szkarłatnego Klasztoru. Krzyczałem i wrzeszczałem. Opowiadałem tę historię każdemu, kto chciał słuchać. Za to zostałem z zimną krwią zamordowany i zawleczony do tej komnaty – mrocznego sekretu zakonu. Ale niektórzy słuchali... niektórzy usłyszeli moje słowa. Tak narodził się Argentowy Brzask...', '', 0),
(12509, 'plPL', 'Niesamowitą historię opowiadasz, Fairbanks. A co z ostrzem? Czy nie da się go już odkupić?', 'Niesamowitą historię opowiadasz, Fairbanks. A co z ostrzem? Czy nie da się go już odkupić?', 0),
(12510, 'plPL', 'Obawiam się, że ostrza, które trzymasz w dłoniach, nie da się już ocalić. Nienawiść sięga zbyt głęboko. Ale nie trać nadziei, $N. Gdy jeden rozdział się kończy, zaczyna się nowy.$B$BOdnajdź jego syna – bardziej pobożnego i oddanego wierze człowieka możesz nigdy nie spotkać. Krążą pogłoski, że potrafi wykuć Spopielacz na nowo, bez starego, splugawionego ostrza.', '', 0),
(12511, 'plPL', 'Ale jego syn nie żyje.', 'Ale jego syn nie żyje.', 0),
(12512, 'plPL', '<Nadinkwizytor Fairbanks kręci głową.>$B$BNie – nie żyje tylko jeden z jego synów. Drugi żyje...$B$B<Nadinkwizytor Fairbanks wskazuje niebo.>$B$BRubież... Tam go szukaj... ', '', 0),
(12626, 'plPL', 'Chcesz powiedzieć...', '', 0),
(18939, 'plPL', 'Skąd to wszystko wiesz?', 'Skąd to wszystko wiesz?', 0),
(22742, 'plPL', 'Dyniowa głowa tli się złowieszczo...', '', 0),
(22746, 'plPL', 'Wezwij Bezgłowego Jeźdźca.', 'Wezwij Bezgłowego Jeźdźca.', 0);
